args<-commandArgs(trailingOnly=TRUE);if(length(args)<5)stop("Usage: fit_nomogram.R <dev.csv> <val.csv> <out> <12,36,60> <vars>");req<-c("survival","rms");if(any(!vapply(req,requireNamespace,logical(1),quietly=TRUE)))stop("Install survival and rms")
dev<-read.csv(args[1],check.names=FALSE);val<-read.csv(args[2],check.names=FALSE);out<-args[3];tt<-as.numeric(strsplit(args[4],",",fixed=TRUE)[[1]]);vars<-strsplit(args[5],",",fixed=TRUE)[[1]];dir.create(out,recursive=TRUE,showWarnings=FALSE)
dd<-rms::datadist(dev);old<-options(datadist="dd");on.exit(options(old),add=TRUE);f<-as.formula(paste("survival::Surv(Time,Event)~",paste(vars,collapse="+")));fit<-rms::cph(f,data=dev,x=TRUE,y=TRUE,surv=TRUE)
sf<-rms::Survival(fit);fun<-lapply(tt,function(t)function(lp)sf(t,lp));pdf(file.path(out,"nomogram.pdf"),width=11.7,height=8.3);plot(rms::nomogram(fit,fun=fun,funlabel=paste0(tt,"-unit survival")));dev.off()
write.csv(data.frame(Time=dev$Time,Event=dev$Event,Nomogram=predict(fit,dev,type="lp")),file.path(out,"development_nomogram_score.csv"),row.names=FALSE);write.csv(data.frame(Time=val$Time,Event=val$Event,Nomogram=predict(fit,val,type="lp")),file.path(out,"validation_nomogram_score.csv"),row.names=FALSE);saveRDS(fit,file.path(out,"nomogram_model.rds"))
